import { createWriteStream } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { Readable, Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';
const data = [{ menu: 'Kopi', jumlah: 3 }, { menu: 'Teh', jumlah: 5 }];
const saring = new Transform({
  objectMode: true,
  transform(x, enc, cb) {
    if (x.jumlah > 3) cb(null, x);
    else cb();
  },
});
const keCsv = new Transform({
  objectMode: true,
  transform(x, enc, cb) {
    cb(null, `${x.menu},${x.jumlah}\n`);
  },
});
await pipeline(Readable.from(data), saring, keCsv, createWriteStream('jual.csv'));
console.log(await readFile('jual.csv', 'utf8'));

