import { Readable, Transform, Writable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
const hasil = [];
await pipeline(
  Readable.from(['a', 'b']),
  new Transform({ objectMode: true, transform(c, e, cb) { cb(null, c.toUpperCase()); } }),
  new Writable({ objectMode: true, write(c, e, cb) { hasil.push(c); cb(); } }),
);
console.log(hasil);

