import { Readable, Transform, Writable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
let total = 0;
await pipeline(
  Readable.from([1, 2, 3]),
  new Transform({ objectMode: true, transform(n, e, cb) { cb(null, n * 10); } }),
  new Writable({ objectMode: true, write(n, e, cb) { total += n; cb(); } }),
);
console.log('Total:', total);
